\documentclass[tikz, border=3mm]{standalone}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}
\usetikzlibrary{decorations.markings,decorations.pathmorphing}
\begin{document}

	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

	\pagestyle{empty}
	\begin{tikzpicture}

	\def\tstart{0}		% in radians
	\def\tend{pi/2}		% in radians
	\def\tstartlabel{(4,0)}	% Coordinates of starting point
	\def\tendlabel{(0,4)}		% Coordinates of ending point
	\def\xr{4}		% x-radius
	\def\yr{4}		% y-radius
	\def\add{0.03}	% label C moved further out

	\def\tmid{(\tstart+\tend)/2}

	\begin{axis}[scale = 1.0,
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend pos=outer north east,
	legend style={font=\footnotesize},
	trig format plots=rad,
	tick style={draw=none},
	axis line style = thick,
	axis y line = center,
	axis x line = middle,
	axis equal,
	%	grid = both,
	xmin = -1,
	xmax = 5,
	ymin = -1,
	ymax = 5,
	xtick = {4},
	ytick = {4},
	xticklabels = {$4$},
	yticklabels = {$4$},	
	%% Here, we can control the positioning of each individual tick.
	x tick label style={xshift={(\tick==2)*5pt}},
	%y tick label style={xshift={(\tick==-1)*19pt}},
	%y tick label style={xshift={(\tick==1)*14pt}},
	xlabel = {$x$},
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above left},
	every axis x label/.style={
		at={(ticklabel* cs:1.02)},
		anchor=west,
	},
	every axis y label/.style={
		at={(ticklabel* cs:1.02)},
		anchor=south,
	}
	]

	% Curve
	\plot[
	domain = {\tstart}:{\tend},
	samples = 100,
	color = deepskyblue,
	line width = 1.2pt,
	decoration={
		markings,
		mark=between positions 0.2 and 1 step 0.3 with {\arrow[]{>};}
	},
	postaction={decorate}
	]
	({\xr*cos(\x)},{\yr*sin(\x)});

	\node[label={[above right, deepskyblue]:{\small $C$}}] at (axis cs:{(\xr+\add)*cos(deg(\tmid))},{(\yr+\add)*sin(deg(\tmid))}) {};

	% End points
	\draw[draw=none, fill=deepskyblue] (axis cs:{\xr*cos(deg(\tstart))},{\yr*sin(deg(\tstart))}) circle (2.0pt);
	%	\node[label={[right, yshift=-2pt]:{\small $\displaystyle \tstartlabel$}}] at (axis cs:{\xr*cos(deg(\tstart))},{\yr*sin(deg(\tstart))}) {};
	\draw[draw=none, fill=deepskyblue] (axis cs:{\xr*cos(deg(\tend))},{\yr*sin(deg(\tend))}) circle (2.0pt);
	%	\node[label={[above, yshift=-2pt]:{\small $\displaystyle \tendlabel$}}] at (axis cs:{\xr*cos(deg(\tend))},{\yr*sin(deg(\tend))}) {};

	\end{axis}
	\end{tikzpicture}
\end{document}
